// Compiles tokens/core.json with Style Dictionary into every surface's theme file.
//   web:  src/styles/tokens.css  (CSS variables, colours in OKLCH; dark = :root, light / hc = [data-theme])
//   3D:   src/styles/tokens.ts   (hex numbers for Three.js materials)
//   Qt:   ../jarvis/ui/theme/tokens.py and jarvis{,.light,.hc}.qss
// Run: npm run tokens. CI fails when a generated file is stale.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import StyleDictionary from 'style-dictionary';
import { parseColor, toOklch, toQss, toHexNumber } from './color.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const core = JSON.parse(readFileSync(join(root, 'tokens', 'core.json'), 'utf8'));
const THEMES = ['dark', 'light', 'hc'];
const HEADER = 'Generated by frontend/scripts/build-tokens.mjs from frontend/tokens/core.json. Do not edit.';

/** Resolve the full token set for a theme with Style Dictionary and return [{name, type, value}]. */
async function resolve(theme, transformName) {
    const tokens = { ...core.base, ...core.themes.dark, ...(theme === 'dark' ? {} : core.themes[theme]) };
    const sd = new StyleDictionary({
        tokens,
        log: { verbosity: 'silent', warnings: 'disabled' },
        hooks: {
            transforms: {
                'color/oklch': { type: 'value', filter: (t) => t.$type === 'color', transform: (t) => toOklch(t.$value) },
                'color/raw': { type: 'value', filter: (t) => t.$type === 'color', transform: (t) => t.$value },
            },
        },
        platforms: { out: { transforms: ['name/kebab', transformName] } },
    });
    const dict = await sd.getPlatformTokens('out');
    return dict.allTokens.map((t) => ({ name: t.name, type: t.$type, value: t.$value, raw: t.original.$value, description: t.$description }));
}

const block = (selector, rows) =>
    `${selector} {\n${rows.map((r) => `  --${r.name}: ${r.value};${r.description ? ` /* ${r.description} */` : ''}`).join('\n')}\n}\n`;

async function main() {
    const web = Object.fromEntries(
        await Promise.all(THEMES.map(async (t) => [t, (await resolve(t, 'color/oklch')).filter((r) => !r.name.startsWith('stage-'))])),
    );
    // stage-* colours feed only the 3D stage (tokens.ts); they are not CSS variables.
    const raw = Object.fromEntries(await Promise.all(THEMES.map(async (t) => [t, await resolve(t, 'color/raw')])));
    const only = (theme) => {
        const names = new Set(Object.keys(core.themes[theme]));
        return web[theme].filter((r) => names.has(r.name));
    };
    // Only motion durations drop to 0 for reduced motion; how long a toast stays is not motion.
    const durations = web.dark.filter((r) => r.type === 'duration' && r.name !== 'dur-toast');

    // ── web CSS ──────────────────────────────────────────────────────────────
    const css =
        `/* ${HEADER} */\n` +
        block(':root', web.dark) +
        '\n' +
        block(":root[data-theme='light']", only('light')) +
        '\n' +
        block(":root[data-theme='hc']", only('hc')) +
        '\n@media (prefers-contrast: more) {\n' +
        block("  :root:not([data-theme='light'])", only('hc'))
            .replace(/^ {2}--/gm, '    --')
            .replace(/^}/m, '  }') +
        '}\n' +
        '\n@media (prefers-reduced-motion: reduce) {\n  :root {\n' +
        durations.map((r) => `    --${r.name}: 0ms;`).join('\n') +
        '\n  }\n}\n';
    writeFileSync(join(root, 'src', 'styles', 'tokens.css'), css);

    // ── 3D stage (Three.js wants numbers) ────────────────────────────────────
    const colorsOf = (theme) => raw[theme].filter((r) => r.type === 'color');
    const ts =
        `// ${HEADER}\n/** Theme colours as 0xRRGGBB plus alpha, for Three.js materials. */\n` +
        `export const STAGE_TOKENS = {\n` +
        THEMES.map(
            (t) =>
                `    ${t}: {\n` +
                colorsOf(t)
                    .map((r) => {
                        const c = parseColor(r.raw);
                        return `        '${r.name}': { hex: ${toHexNumber(c)}, alpha: ${+c.a.toFixed(3)} },`;
                    })
                    .join('\n') +
                '\n    },',
        ).join('\n') +
        `\n} as const;\nexport type ThemeName = keyof typeof STAGE_TOKENS;\nexport type TokenName = keyof (typeof STAGE_TOKENS)['dark'];\n` +
        `\n/** Durations in milliseconds, for JS-driven motion. Same values as the --dur-* CSS variables. */\nexport const DURATIONS = {\n` +
        raw.dark
            .filter((r) => r.type === 'duration')
            .map((r) => `    '${r.name}': ${parseFloat(r.raw)},`)
            .join('\n') +
        `\n} as const;\n`;
    writeFileSync(join(root, 'src', 'styles', 'tokens.ts'), ts);

    // ── Qt: tokens.py + QSS ──────────────────────────────────────────────────
    const qtDir = join(root, '..', 'jarvis', 'ui', 'theme');
    mkdirSync(qtDir, { recursive: true });
    const pyDict = (rows) =>
        '{\n' +
        rows.map((r) => `        ${JSON.stringify(r.name)}: ${JSON.stringify(r.type === 'color' ? toQss(r.raw) : String(r.raw))},`).join('\n') +
        '\n    }';
    const py =
        `"""${HEADER}\n\nTHEMES[name][token] holds Qt-ready values: colours as #rrggbb or rgba(r, g, b, a 0-255),\nother tokens as their CSS text (px, ms). OKLCH[name][token] is what the web CSS uses for the same colour.\n"""\n` +
        `THEMES: dict[str, dict[str, str]] = {\n` +
        THEMES.map((t) => `    ${JSON.stringify(t)}: ${pyDict(raw[t])},`).join('\n') +
        `\n}\n\nOKLCH: dict[str, dict[str, str]] = {\n` +
        THEMES.map(
            (t) =>
                `    ${JSON.stringify(t)}: {\n` +
                web[t]
                    .filter((r) => r.type === 'color')
                    .map((r) => `        ${JSON.stringify(r.name)}: ${JSON.stringify(r.value)},`)
                    .join('\n') +
                '\n    },',
        ).join('\n') +
        `\n}\n\n\ndef token(name: str, theme: str = "dark") -> str:\n    return THEMES.get(theme, THEMES["dark"]).get(name) or THEMES["dark"][name]\n`;
    writeFileSync(join(qtDir, 'tokens.py'), py);
    const template = readFileSync(join(here, 'qss.template'), 'utf8');
    for (const t of THEMES) {
        const values = Object.fromEntries(raw[t].map((r) => [r.name, r.type === 'color' ? toQss(r.raw) : String(r.raw)]));
        const qss =
            `/* ${HEADER} Theme: ${t}. */\n` +
            template.replace(/\{\{([a-z0-9-]+)\}\}/g, (_, n) => {
                if (!(n in values)) throw new Error(`qss.template uses unknown token ${n}`);
                return values[n];
            });
        writeFileSync(join(qtDir, t === 'dark' ? 'jarvis.qss' : `jarvis.${t}.qss`), qss);
    }
    console.log(`tokens: ${web.dark.length} tokens x ${THEMES.length} themes -> css, ts, py, qss`);
}

main().catch((e) => {
    console.error(e);
    process.exit(1);
});
